/**
 * video-demo — vendored from the UI Engine preset library (axiestudio).
 * Install: npx shadcn@latest add https://ui-engine.pages.dev/r/video-demo.json
 * Source of truth: UI/ — do not edit vendored copies blindly.
 */
import * as React from "react"
import { Play } from "lucide-react"
import { InView } from "@/components/primitives/in-view"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogTitle } from "@/components/ui/dialog"
import { cn } from "@/lib/utils"
import { Iphone17Pro } from "@/components/eldora/iphone-17-pro"
import { Ipad } from "@/components/eldora/ipad"

// ── Types ────────────────────────────────────────────────────────────────────
export type VideoDemoProps = {
  eyebrow?: string
  title?: string
  subtitle?: string
  /** Poster image for the framed player. */
  poster?: string
  posterAlt?: string
  /** Embed URL loaded in the lightbox (YouTube/Vimeo embed or direct mp4). */
  src?: string
  /** mp4 when true renders a native <video controls>, otherwise an <iframe>. Default false. */
  direct?: boolean
  playLabel?: string
  /** Text shown in the browser-chrome bar. */
  urlLabel?: string
  caption?: string
  tone?: "paper" | "ink"
  className?: string
}

// ── Device-framed poster (Eldora mockups) ────────────────────────────────────
// Tablet/mobile get the registry device mockup; desktop keeps the flat browser-chrome card.

function DevicePoster({
  poster,
  posterAlt,
  playLabel,
  onOpen,
  ink,
}: {
  poster: string
  posterAlt: string
  playLabel: string
  onOpen: () => void
  ink: boolean
}) {
  return (
    <div className="flex justify-center">
      {/* tablet — Eldora iPad (engine tablet sim = 768px window) */}
      <Button
        type='button'
        onClick={onOpen}
        aria-label={playLabel}
        className="relative hidden h-auto w-full max-w-[520px] overflow-hidden rounded-[28px] border-0 bg-transparent p-0 shadow-2xl transition-transform duration-300 hover:scale-[1.01] md:block lg:hidden"
        variant="default"
      >
        <Ipad width={520} height={400} className="!h-auto !w-full" aria-hidden />
        <span className="absolute left-[6.03%] top-[7.12%] h-[85.72%] w-[87.93%] overflow-hidden rounded-[9px] bg-muted">
          <img src={poster} alt={posterAlt} className="h-full w-full object-cover object-top" loading="lazy" />
          <span className="absolute inset-0 flex items-center justify-center">
            <span className={cn(
              "flex size-14 items-center justify-center rounded-full shadow-xl",
              ink ? "bg-background text-foreground" : "bg-foreground text-background",
            )}>
              <Play className="ml-0.5 size-5 fill-current" />
            </span>
          </span>
        </span>
      </Button>

      {/* mobile — Eldora iPhone 17 Pro, sub-md viewports */}
      <Button
        type='button'
        onClick={onOpen}
        aria-label={playLabel}
        className="relative block h-auto w-full max-w-[270px] overflow-hidden rounded-[40px] border-0 bg-transparent p-0 shadow-2xl transition-transform duration-300 hover:scale-[1.01] md:hidden"
        variant="default"
      >
        <Iphone17Pro width={200} height={400} className="!h-auto !w-full" aria-hidden />
        <span className="absolute left-[7.04%] top-[3.2%] h-[93.59%] w-[85.99%] overflow-hidden rounded-[32px] bg-muted">
          <img src={poster} alt={posterAlt} className="h-full w-full object-cover object-top" loading="lazy" />
          <span className="absolute inset-0 flex items-center justify-center">
            <span className={cn(
              "flex size-12 items-center justify-center rounded-full shadow-xl",
              ink ? "bg-background text-foreground" : "bg-foreground text-background",
            )}>
              <Play className="ml-0.5 size-5 fill-current" />
            </span>
          </span>
        </span>
      </Button>
    </div>
  )
}

// ── VideoDemo ────────────────────────────────────────────────────────────────

// Self-demo defaults: a bare mount (tablet/mobile device frames, library consumers)
// reproduces the same demo the engine desktop view shows.
const DEMO_VIDEO_DEMO_POSTER = "/showcase/hero-poster.webp"
const DEMO_VIDEO_DEMO_SRC = "https://www.youtube.com/embed/dQw4w9WgXcQ"


export function VideoDemo({
  eyebrow,
  title = "See it in motion",
  subtitle,
  poster = DEMO_VIDEO_DEMO_POSTER,
  posterAlt = "Product demo video",
  src = DEMO_VIDEO_DEMO_SRC,
  direct = false,
  playLabel = "Play demo",
  urlLabel = "demo.example.com",
  caption,
  tone = "ink",
  className,
}: VideoDemoProps) {
  const [open, setOpen] = React.useState(false)
  const ink = tone === "ink"

  return (
    <section className={cn(ink && "bg-foreground", "relative isolate flex min-h-screen w-full flex-col overflow-hidden", className)} aria-label={title}>
      <div className="mx-auto flex w-full max-w-[1280px] flex-1 flex-col justify-center px-5 py-16 sm:px-8 sm:py-24">
        {(eyebrow || title || subtitle) && (
          <header className="mx-auto mb-10 max-w-2xl text-center sm:mb-14">
            {eyebrow && (
              <p className={cn("font-mono text-[11px] font-bold uppercase tracking-widest", ink ? "text-background/50" : "text-muted-foreground")}>
                {eyebrow}
              </p>
            )}
            {title && (
              <h2 className={cn("mt-2 font-display text-3xl font-bold tracking-[-0.03em] sm:text-4xl", ink ? "text-background" : "text-foreground")}>
                {title}
              </h2>
            )}
            {subtitle && (
              <p className={cn("mt-3 text-base font-medium leading-relaxed", ink ? "text-background/70" : "text-muted-foreground")}>
                {subtitle}
              </p>
            )}
          </header>
        )}

        <InView
          variants={{ hidden: { opacity: 0, y: 24, scale: 0.98 }, visible: { opacity: 1, y: 0, scale: 1 } }}
          transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
          viewOptions={{ once: true, margin: "-80px" }}
        >
          {/* tablet + mobile — registry device mockups */}
          <figure className="group relative mx-auto max-w-4xl lg:hidden">
            <DevicePoster poster={poster} posterAlt={posterAlt} playLabel={playLabel} onOpen={() => setOpen(true)} ink={ink} />
            {caption && (
              <figcaption className={cn("mt-4 text-center text-sm font-medium", ink ? "text-background/60" : "text-muted-foreground")}>
                {caption}
              </figcaption>
            )}
          </figure>

          {/* desktop — browser-chrome card, unchanged */}
          <figure className="group relative mx-auto hidden max-w-4xl lg:block">
            <Button type='button' onClick={() => setOpen(true)} aria-label={playLabel} className={cn(
                "relative block h-auto w-full overflow-hidden rounded-[20px] border text-left shadow-2xl transition-transform duration-300 group-hover:scale-[1.01]",
                ink ? "border-background/20 bg-background/5" : "border-border bg-card",
              )} variant="default">
              <div className={cn("flex items-center gap-3 border-b px-4 py-3", ink ? "border-background/10 bg-background/5" : "border-border bg-muted/50")}>
                <span className="flex gap-1.5" aria-hidden>
                  <i className={cn("size-2.5 rounded-full", ink ? "bg-background/30" : "bg-muted-foreground/30")} />
                  <i className={cn("size-2.5 rounded-full", ink ? "bg-background/30" : "bg-muted-foreground/30")} />
                  <i className={cn("size-2.5 rounded-full", ink ? "bg-background/30" : "bg-muted-foreground/30")} />
                </span>
                <span className={cn("mx-auto hidden max-w-xs truncate rounded-full px-3 py-1 font-mono text-[11px] sm:block", ink ? "bg-background/10 text-background/60" : "bg-background text-muted-foreground")}>
                  {urlLabel}
                </span>
                <span className="w-10" aria-hidden />
              </div>
              <div className="relative aspect-video w-full overflow-hidden bg-muted">
                <img src={poster} alt={posterAlt} className="h-full w-full object-cover object-top" loading="lazy" />
                <span className="absolute inset-0 bg-gradient-to-t from-foreground/50 via-transparent to-transparent" aria-hidden />
                <span className="absolute inset-0 flex items-center justify-center">
                  <span className={cn(
                    "flex size-16 items-center justify-center rounded-full shadow-xl transition-transform duration-300 group-hover:scale-110 sm:size-20",
                    ink ? "bg-background text-foreground" : "bg-foreground text-background",
                  )}>
                    <Play className="ml-1 size-6 fill-current sm:size-7" />
                  </span>
                </span>
              </div>
            </Button>
            {caption && (
              <figcaption className={cn("mt-4 text-center text-sm font-medium", ink ? "text-background/60" : "text-muted-foreground")}>
                {caption}
              </figcaption>
            )}
          </figure>
        </InView>
      </div>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="!max-w-none w-[min(56rem,calc(100%-2rem))] gap-0 overflow-hidden border-none bg-foreground p-0">
          <DialogTitle className="sr-only">{title}</DialogTitle>
          <div className="aspect-video w-full">
            {direct ? (
              <video src={src} poster={poster} controls autoPlay className="h-full w-full" />
            ) : (
              <iframe
                src={src}
                title={title}
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                allowFullScreen
                className="h-full w-full"
              />
            )}
          </div>
          <div className="flex justify-end px-4 py-3">
            <Button variant="ghost" size="sm" className="text-background hover:bg-background/10 hover:text-background" onClick={() => setOpen(false)}>
              Close
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </section>
  )
}

/* video-demo companion styles — @import this file in your CSS (tokens come from your theme). */
/* ─── Professional DND Design System ─────────────────────────────────────
   Neutral, calm palette tuned for productivity surfaces. Tokens stay
   compatible with shadcn theming so engine re-themes still work.
   Drag states are subtle but unmistakable.
────────────────────────────────────────────────────────────────────────── */




/* ─── Drag & Drop polish ──────────────────────────────────────────────── */
.dnd-lift {
  box-shadow: 0 10px 28px -10px hsl(var(--foreground) / 0.2), 0 4px 10px -4px hsl(var(--foreground) / 0.1);
  outline: 1.5px solid hsl(var(--ring) / 0.9);
  outline-offset: 0;
  transform: rotate(0.6deg) scale(1.015);
  z-index: 50;
}
.dnd-over {
  outline: 1.5px dashed hsl(var(--ring) / 0.45);
  outline-offset: 2px;
  background: hsl(var(--accent) / 0.5);
}

/* Smooth sortable transitions */
[data-sortable] { will-change: transform; }
